using System;using System.Collections.Generic;public class Solution{public IList<int> LargestDivisibleSubset(int[]a){var o=new List<int>();if(a.Length==0)return o;Array.Sort(a);int n=a.Length,b=0;int[]d=new int[n],p=new int[n];Array.Fill(d,1);Array.Fill(p,-1);for(int i=0;i<n;i++){for(int j=0;j<i;j++)if(a[i]%a[j]==0&&d[j]+1>d[i]){d[i]=d[j]+1;p[i]=j;}if(d[i]>d[b])b=i;}for(int i=b;i!=-1;i=p[i])o.Add(a[i]);o.Reverse();return o;}}
